import json, time
from _pytest._code.code import ExceptionInfo, Traceback
STATES = iter(())

def walk(state):
    walk(next(STATES))

def capture(states):
    global STATES
    STATES = iter(states)
    try:
        walk(next(STATES))
    except StopIteration:
        exc = ExceptionInfo.from_current()
    return Traceback((entry for entry in exc.traceback if entry.frame.code.raw is walk.__code__))

class CountedValue:
    calls = 0

    def __init__(self, value):
        self.value = value

    def __eq__(self, other):
        type(self).calls += 1
        return type(other) is type(self) and self.value == other.value
    __hash__ = None
rows=[]
for n in (20,40,80,160):
    trace=capture([CountedValue(i) for i in range(n)])
    CountedValue.calls=0; start=time.perf_counter()
    try:
        index=trace.recursionindex(); status='exact_search_completed'; error=None
    except Exception as exc:
        index=None; status='origin_unknown'; error=type(exc).__name__
    rows.append(dict(frames=len(trace),index=index,status=status,error=error,equality_calls=CountedValue.calls,wall_seconds=time.perf_counter()-start))
print(json.dumps(rows,indent=2))
